from pathlib import Path


def between(text,start,end,replacement,path):
    a=text.find(start)
    b=text.find(end,a+len(start))
    if a<0 or b<0:
        raise SystemExit(f'block not found in {path}: {start} .. {end}')
    return text[:a]+replacement+text[b:]

