bind=r'''function selectLayoutMenu(out,key){const root=out.querySelector('[data-layout-studio]');if(!root)return;root.querySelectorAll('[data-layout-menu-select]').forEach(b=>{const active=b.dataset.layoutMenuSelect===key;b.classList.toggle('is-active',active);b.setAttribute('aria-pressed',active?'true':'false')});root.querySelectorAll('[data-layout-panel]').forEach(panel=>{panel.hidden=panel.dataset.layoutPanel!==key})}
function bindAppEditor(out){out.querySelectorAll('[data-move-up]').forEach(b=>b.onclick=()=>moveRow(b,-1));out.querySelectorAll('[data-move-down]').forEach(b=>b.onclick=()=>moveRow(b,1));out.querySelectorAll('[data-layout-menu-select]').forEach(b=>b.addEventListener('click',()=>selectLayoutMenu(out,b.dataset.layoutMenuSelect)));out.querySelector('[data-app-save]')?.addEventListener('click',saveAppLayout);out.querySelector('[data-app-reset]')?.addEventListener('click',resetAppLayout)}
'''
