new_model=r'''function menuItemView(g,item,index,groupSettings){const items=groupSettings?.items||{},s=items[menuItemKey(g,item)]||items[legacyMenuItemKey(g,item)]||{},x=[...item],order=Number(s.order);x[0]=String(s.label||item?.[0]||'');x[1]=String(s.icon||item?.[1]||'');x.__menuColor=validMenuColor(s.color);x.__menuVisible=s.visible!==false;x.__menuOrder=Number.isFinite(order)?order:(index+1)*10;x.__menuSourceGroup=g.key;x.__menuTargetGroup=String(s.targetGroup||g.key);return x}
function configuredMenuItems(targetKey){const cfg=menuLayoutConfig(),all=[];MENU_GROUPS.forEach(source=>{const gs=cfg?.groups?.[source.key]||{};(source.items||[]).forEach((item,i)=>{const x=menuItemView(source,item,i,gs);x.__menuSection='main';if(x.__menuTargetGroup===targetKey)all.push(x)});(source.subItems||[]).forEach((item,i)=>{const x=menuItemView(source,item,(source.items||[]).length+i,gs);x.__menuSection=source.key===targetKey?'sub':'main';if(x.__menuTargetGroup===targetKey)all.push(x)})});return all}
function menuGroupView(g,index){const s=menuLayoutConfig()?.groups?.[g.key]||{},order=Number(s.order),x={...g},all=configuredMenuItems(g.key).filter(item=>item.__menuVisible);x.label=String(s.label||g.label||'');x.icon=String(s.icon||g.icon||'');x.__menuColor=validMenuColor(s.color);x.__menuVisible=s.visible!==false;x.__menuOrder=Number.isFinite(order)?order:(index+1)*10;x.items=all.filter(item=>item.__menuSection!=='sub').sort((a,b)=>a.__menuOrder-b.__menuOrder);x.subItems=all.filter(item=>item.__menuSection==='sub').sort((a,b)=>a.__menuOrder-b.__menuOrder);return x}
function visibleItems(g){return(g.items||[]).filter(itemAllowed).concat((g.subItems||[]).filter(itemAllowed))}
function visibleGroups(){return MENU_GROUPS.filter(g=>g.hidden!==true)}
function customizedVisibleGroups(){return visibleGroups().map((g,index)=>menuGroupView(g,index)).filter(g=>g.__menuVisible!==false&&teacherMenuGroupAllowed(g)&&visibleItems(g).length).sort((a,b)=>a.__menuOrder-b.__menuOrder)}
'''
s=between(s,'function menuItemView(g,item,index,groupSettings)','function menuCount(g)',new_model,'js/core/shell-ui.js')
