new="function bindMenuRoutes(root){$$('[data-ka-shell-route]',root).forEach(b=>b.addEventListener('click',()=>{if(menuGroup){const g=customizedVisibleGroups().find(x=>x.key===menuGroup);rememberView({kind:'menu-list',name:'menu',bottom:'menu',page:menuGroup,title:g?.label||'Menü'})}routeModule(b.dataset.kaShellRoute,{bottom:'menu',page:b.dataset.kaShellPage||'',title:b.dataset.kaShellTitle||''})}))}"
