new="async function restoreView(view){if(!view)return false;if(view.kind==='profile'){renderProfile({remember:false});return true}if(view.kind==='profile-detail'){renderProfileDetail(view.page,{remember:false});return true}if(view.kind==='search'){renderSearch({remember:false});return true}if(view.kind==='menu-list'){openMenu();renderMenuList(view.page);return true}if(view.kind==='route')return routeModule(view.name,{bottom:view.bottom||'menu',page:view.page||'',title:view.title||'',remember:false});return false}"
