s=between(s,'/* Duty report — adaptive full-page A4 roster. */','/* Announcements page — canonical communication redesign. */',duty,'css/design-system.css')
old_start='.ka-settings-menu-group>summary{cursor:pointer}'
old_end='@media(max-width:380px){.ka-menu-list>.ka-btn{min-height:54px}'
