if a<0 or b<0: raise SystemExit('settings menu css block missing')
studio=r'''.ka-layout-page{gap:14px}.ka-layout-intro h3{margin:7px 0 3px}.ka-layout-studio{display:grid;gap:12px}.ka-layout-picker{display:flex;gap:8px;overflow-x:auto;padding:2px 1px 7px;scroll-snap-type:x proximity;scrollbar-width:none}.ka-layout-picker::-webkit-scrollbar{display:none}.ka-layout-picker__item{min-width:148px;max-width:190px;min-height:68px;display:grid;grid-template-columns:32px minmax(0,1fr) 24px;align-items:center;gap:7px;padding:9px 10px;border:1px solid var(--ka-border);border-radius:15px;background:var(--ka-card-bg);color:var(--ka-text);text-align:left;scroll-snap-align:start}.ka-layout-picker__item>span{font-size:21px}.ka-layout-picker__item strong{font-size:11.5px;line-height:1.15}.ka-layout-picker__item small{display:grid;place-items:center;width:24px;height:24px;border-radius:999px;background:var(--ka-muted-bg);color:var(--ka-text-muted);font-size:9px;font-weight:800}.ka-layout-picker__item.is-active{border-color:var(--ka-primary);background:var(--ka-primary-soft);box-shadow:0 0 0 2px color-mix(in srgb,var(--ka-primary) 16%,transparent)}.ka-layout-panels{min-height:0}.ka-layout-menu-panel[hidden]{display:none!important}.ka-layout-menu-panel__head{align-items:center}.ka-layout-menu-panel__head small{display:block;margin-top:2px}.ka-settings-menu-swatch{width:12px;height:42px;flex:0 0 12px;border-radius:999px;background:var(--ka-settings-menu-color)}.ka-settings-menu-fields{display:grid;grid-template-columns:minmax(0,1.4fr) 90px 84px 74px;gap:8px}.ka-settings-menu-fields--item{grid-template-columns:minmax(0,1.25fr) 80px minmax(135px,.8fr) 74px 66px}.ka-settings-menu-item{padding:11px;border:1px solid var(--ka-border);border-radius:14px;background:var(--ka-muted-bg);display:grid;gap:9px}.ka-settings-menu-item small{display:block;margin-top:2px;font-size:9px}.ka-settings-color-field input[type="color"]{padding:4px;min-height:44px}.ka-layout-items-head h4{margin:0 0 2px}.ka-layout-items-head p{margin:0;font-size:10px}.ka-layout-savebar{position:sticky;bottom:calc(var(--ka-bottom-nav-h) + 8px);z-index:8;display:grid;grid-template-columns:1fr 1.35fr;gap:8px;padding:9px;border:1px solid var(--ka-border);border-radius:16px;background:color-mix(in srgb,var(--ka-card-raised-bg) 94%,transparent);box-shadow:var(--ka-shadow-md);backdrop-filter:blur(14px)}
@media(max-width:700px){.ka-settings-menu-fields,.ka-settings-menu-fields--item{grid-template-columns:minmax(0,1fr) 86px}.ka-settings-menu-fields--item .ka-field:has([data-menu-item-target]){grid-column:1/-1}.ka-settings-color-field input[type="color"]{min-height:42px}.ka-layout-menu-panel__head{padding:12px}.ka-layout-menu-panel>.ka-card__body{padding:12px}.ka-layout-savebar{bottom:calc(var(--ka-bottom-nav-h) + 5px)}}
'''
